window.profileUi = (() => {
  const esc=accountEscape;
  const icons={stats:'<path d="M4 21h16M6 17v-5m6 5V4m6 13V8"/><circle cx="6" cy="8" r="1"/><circle cx="18" cy="4" r="1"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',daily:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 6 3 3 5-6"/>',find:'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4m-9 4v10M7 5l10 4v5"/>',sale:'<path d="M3 7h18l-2 6H5L3 7Zm2 6v8h14v-8m-9 8v-6h4v6M5 7V3h14v4"/>',reinvest:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 2M18 18A8 8 0 0 1 5 16"/>',friends:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5"/>',record:'<path d="M6 3h12v18H6V3Zm3 5h6m-6 4h6m-6 4h4"/>',check:'<path d="m5 12 4 4L19 6"/>'};
  const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.star}</svg>`;
  const selectedTab=()=>['overview','statistics','friends','record'].includes(new URLSearchParams(location.search).get('tab'))?new URLSearchParams(location.search).get('tab'):'overview';
  function hero(){
    const p=account.progression,level=p.level;
    return `<header class="profile-hero"><div class="profile-level-seal" aria-hidden="true"><span>${icon('star')}</span><small>LEVEL</small><strong>${number(level)}</strong><svg class="profile-laurel" viewBox="0 0 140 160" fill="none"><path d="M37 133C5 110 5 64 32 37m-12 18-8-14m6 32L4 62m15 28L3 85m23 22-18-3m95 29c32-23 32-69 5-96m12 18 8-14m-6 32 14-11m-15 28 16-5m-23 22 18-3" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></div><div class="profile-identity"><h1 tabindex="-1">${esc(account.username)}</h1><p class="profile-title">${t('Level','Level')} ${number(level)}</p><div class="profile-xp-caption"><span>${number(p.xp)} XP</span><strong>${p.nextLevelXp===null?t('Max level reached','Maximallevel erreicht'):t(`${number(p.nextLevelXp-p.xp)} XP to level ${level+1}`,`${number(p.nextLevelXp-p.xp)} XP bis Level ${level+1}`)}</strong></div><progress class="profile-xp" max="1" value="${p.progress}" aria-label="${t('Level progress','Levelfortschritt')}"></progress></div><a class="profile-skill-bank" href="/skills" data-page><span>${icon('star')}</span><strong>${number(account.skills?.available||0)}</strong><small>${t(account.skills?.available===1?'skill point':'skill points',account.skills?.available===1?'Skillpunkt':'Skillpunkte')}</small><b>${t('Skills','Skills')} →</b></a></header>`;
  }
  function tabs(tab){
    const accepted=accountFriends.friends.filter(friend=>friend.status==='accepted').length,incoming=accountFriends.friends.filter(friend=>friend.status==='incoming').length;
    const entries=[['overview',t('Overview','Übersicht'),'star',null],['statistics',t('Statistics','Statistiken'),'stats',null],['friends',t('Friends','Freunde'),'friends',incoming?`${incoming} ${t('new','neu')}`:accepted||null],['record',t('Criminal record','Strafregister'),'record',accountCriminalRecord.total||null]];
    return `<div class="profile-tabs" role="tablist" aria-label="${t('Profile sections','Profilbereiche')}">${entries.map(([id,label,symbol,count])=>`<button type="button" role="tab" id="profile-tab-${id}" data-profile-tab="${id}" aria-controls="profile-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}">${icon(symbol)}<span>${label}</span>${count!==null?`<small>${esc(count)}</small>`:''}</button>`).join('')}</div>`;
  }
  function journey(){
    const {done,steps,next}=traderMilestoneState(),completed=steps.filter(([id])=>done.has(id)).length;
    return `<section class="profile-journey" aria-labelledby="profile-journey-title"><header><div><h2 id="profile-journey-title">${t('Milestones','Meilensteine')}</h2></div>${next?`<a class="primary-button profile-next-goal" href="${next[2]}" data-page>${next[1]} →</a>`:`<a class="secondary-button" href="/inventory" data-page>${t('Inventory','Inventar')} →</a>`}</header><div class="profile-journey-caption"><span>${t('Milestones earned','Erreichte Meilensteine')}</span><strong>${completed} / ${steps.length}</strong></div><progress max="${steps.length}" value="${completed}" aria-label="${t('Trader milestones','Händler-Meilensteine')}"></progress><ol class="profile-milestone-path">${steps.map(([id,label],index)=>{const earned=done.has(id),current=next?.[0]===id;return `<li class="profile-milestone ${earned?'is-earned':current?'is-current':'is-upcoming'}" data-milestone="${id}"><span class="profile-milestone-emblem">${icon(earned?'check':id)}</span><div><small>${earned?t('EARNED','ERREICHT'):current?t('UP NEXT','ALS NÄCHSTES'):t('MILESTONE','MEILENSTEIN')} ${!earned?index+1:''}</small><strong>${label}</strong></div></li>`;}).join('')}</ol></section>`;
  }
  function dailyCard(){
    const daily=account.daily,complete=daily?.status==='completed',active=daily?.status==='in_progress',rewards=accountCatalog?.rewards||{daily:1000,dailyScoreBonus:0};
    const earned=account.rewardsByMode?.daily?.earned||0;
    return `<article class="profile-play-card profile-daily-card ${complete?'is-complete':''}"><span class="profile-card-icon">${icon(complete?'check':'daily')}</span><div><h2>${t('Daily','Daily')}</h2><p>${dailyFriendLabel(daily)}</p><span class="profile-reward-chip">${complete?`${justizEuro(earned)} ${t('earned today','heute verdient')}`:`${justizEuro(rewards.daily)} · ${t('1 case','1 Kiste')}`}</span></div><a class="primary-button" href="${complete?'/leaderboard?view=daily':'/'}" data-page>${complete?t('Leaderboard','Rangliste'):active?t('Resume Daily','Daily fortsetzen'):t('Play Daily','Daily spielen')} →</a></article>`;
  }
  const prestigeLabels={profit:()=>t('+25% sale profit','+25% Verkaufsgewinn'),stealth:()=>t('−25% catch chance','−25% Fangchance'),cases:()=>t('−50% case costs','−50% Kistenkosten'),luck:()=>t('+25% luck','+25% Glück'),restocker:()=>t('Restocker','Auffüllservice')};
  const prestigeHelp={profit:()=>t('Adds 25% to positive profit after tracked purchase costs on business sales and auctions. Buyers pay the normal price.','Erhöht positive Gewinne nach erfassten Einkaufskosten bei Ladenverkäufen und Auktionen um 25%. Käufer zahlen den normalen Preis.'),stealth:()=>t('Reduces theft catch odds relatively: 30% becomes 22.5%, or 50% becomes 37.5% with a guard.','Senkt die Fangchance relativ: 30% werden zu 22,5%, mit Sicherheitsdienst werden 50% zu 37,5%.'),cases:()=>t('Halves every Case Store price and refunds half the price of cases won at auction, rounded to whole J€.','Halbiert alle Preise im Kisten-Shop und erstattet den halben Preis bei ersteigerten Kisten, auf ganze J€ gerundet.'),luck:()=>t('Adds 25% relative luck to newly drawn case and palette odds, alongside your Luck skill. Existing sealed contents stay fixed.','Erhöht das relative Glück bei neuen Kisten- und Palettenziehungen um 25%, zusätzlich zum Glücks-Skill. Bereits versiegelte Inhalte bleiben unverändert.'),restocker:()=>t('Automatically refills all your stores from compatible, available inventory items. Respects capacity and auction locks; does not buy stock or spend money.','Füllt alle deine Läden automatisch mit passenden, verfügbaren Inventargegenständen auf. Beachtet Kapazität und Auktionssperren; kauft keine Waren und gibt kein Geld aus.')};
  let prestigeBusy=false,prestigePending=null;
  function prestigeCard(){
    const p=account.prestige;if(!p)return '';
    return `<section class="profile-prestige" aria-labelledby="prestige-title"><header><span class="prestige-emblem">${icon('reinvest')}</span><div><h2 id="prestige-title">Prestige <span>${number(p.count)} / ${number(p.buffs.length+p.choices.length)}</span></h2><p>${!p.choices.length?t('All permanent buffs unlocked','Alle dauerhaften Boni freigeschaltet'):p.blocked?accountError(p.blocked):account.progression.level<10?t('Available at level 10','Ab Level 10 verfügbar'):t('Reset your progress for one permanent buff','Fortschritt für einen dauerhaften Bonus zurücksetzen')}</p></div><button type="button" class="primary-button" data-prestige="open" ${!p.eligible?'disabled':''}>${t('Prestige','Prestige')} ↻</button></header>${p.buffs.length?`<ul class="prestige-owned">${p.buffs.map(id=>`<li>${icon('check')}<span>${prestigeLabels[id]()}</span>${infoTip(prestigeHelp[id](),prestigeLabels[id]())}</li>`).join('')}</ul>`:''}</section>`;
  }
  function closePrestige(){accountContent.querySelector('.prestige-dialog')?.remove();accountContent.querySelector('[data-prestige="open"]')?.focus();}
  function openPrestige(){
    if(!account?.prestige?.eligible||currentAccountPage!=='/profile')return;
    closePrestige();
    const p=account.prestige;
    accountContent.insertAdjacentHTML('beforeend',`<dialog class="prestige-dialog" aria-labelledby="prestige-dialog-title"><form data-prestige-form><header><h2 id="prestige-dialog-title" tabindex="-1">${t('Choose a permanent buff','Dauerhaften Bonus wählen')}</h2><button type="button" class="secondary-button" data-prestige="close" aria-label="${t('Close','Schließen')}">×</button></header><fieldset><legend>${t('Choose one · each buff unlocks once','Einen wählen · jeder Bonus ist einmal freischaltbar')}</legend>${p.choices.map(id=>`<label class="prestige-choice"><input type="radio" name="buffId" value="${id}" required><span><strong>${prestigeLabels[id]()}</strong><small>${prestigeHelp[id]()}</small></span></label>`).join('')}</fieldset><div class="prestige-reset-preview"><strong>${t('Your progress will reset','Dein Fortschritt wird zurückgesetzt')}</strong><p>${t('Money returns to','Geld wird zurückgesetzt auf')} ${justizEuro(p.startingTokens)}. ${t('Items, stores, XP and skills are cleared. Unclaimed rewards and unfinished games are discarded. Login, friends and Prestige buffs remain. Daily rewards already claimed today stay claimed.','Gegenstände, Läden, XP und Skills werden zurückgesetzt. Offene Belohnungen und laufende Spiele entfallen. Login, Freunde und Prestige-Boni bleiben. Bereits erhaltene Daily-Belohnungen bleiben für heute verbraucht.')}</p></div><label class="prestige-confirm"><input type="checkbox" name="confirmation" required>${t('I understand this reset cannot be undone.','Ich verstehe, dass dieser Reset nicht rückgängig gemacht werden kann.')}</label><p class="account-error" data-prestige-error role="alert" hidden></p><button type="submit" class="primary-button">${t('Reset & Prestige','Zurücksetzen & Prestige')}</button></form></dialog>`);
    const dialog=accountContent.querySelector('.prestige-dialog');dialog.showModal();dialog.querySelector('h2').focus();dialog.addEventListener('cancel',event=>{if(prestigeBusy)event.preventDefault();else closePrestige();});
  }
  document.addEventListener('click',event=>{const button=event.target.closest('[data-prestige]');if(!button||prestigeBusy)return;if(button.dataset.prestige==='open')openPrestige();else closePrestige();});
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('[data-prestige-form]');if(!form)return;event.preventDefault();if(prestigeBusy||!account||currentAccountPage!=='/profile'||!form.reportValidity())return;
    const buffId=new FormData(form).get('buffId'),owner=account.id,visit=accountVisit,count=account.prestige.count;
    if(!prestigePending||prestigePending.owner!==owner||prestigePending.buffId!==buffId||prestigePending.expectedCount!==count)prestigePending={owner,buffId,expectedCount:count,requestId:crypto.randomUUID(),confirmation:'PRESTIGE'};
    prestigeBusy=true;form.querySelectorAll('button,input').forEach(el=>el.disabled=true);const error=form.querySelector('[data-prestige-error]');error.hidden=true;
    try{const result=await accountApi('prestige',prestigePending);if(owner!==account?.id||visit!==accountVisit)return;prestigePending=null;updateAccount(result.user);closePrestige();await navigateAccountPage('/profile',false);showToast(t('Prestige buff unlocked','Prestige-Bonus freigeschaltet'));}
    catch(failure){if(owner!==account?.id||visit!==accountVisit)return;error.textContent=failure.message;error.hidden=false;}
    finally{prestigeBusy=false;form.querySelectorAll('button,input').forEach(el=>el.disabled=false);}
  });
  function statTile(label,value,symbol='star',help=''){
    return `<div class="profile-stat-tile"><span class="profile-stat-icon" aria-hidden="true">${icon(symbol)}</span><dt>${esc(label)}${help?infoTip(help,label):''}</dt><dd>${esc(value)}</dd></div>`;
  }
  function statGroup(id,label,symbol,tiles){
    return `<section class="profile-stat-group stat-group-${id}" aria-labelledby="stats-${id}"><header><span aria-hidden="true">${icon(symbol)}</span><h3 id="stats-${id}">${esc(label)}</h3></header><dl>${tiles.join('')}</dl></section>`;
  }
  function statistics(){
    const s=accountStatistics?.userId===account.id?accountStatistics:null;
    if(!s)return `<p role="status">${t('Loading statistics…','Statistiken werden geladen …')}</p>`;
    const {money:m,cases:c,trading:r,stores:b,theft:h,games:g,community:k}=s;
    const earningsNames={store:t('Business sales','Ladenverkäufe'),auction:t('Auction sales','Auktionsverkäufe'),games:t('Game rewards','Spielbelohnungen'),other:t('Gifts, tips & other','Geschenke, Trinkgeld & Sonstiges')};
    const rarityNames={common:t('Common','Gewöhnlich'),uncommon:t('Uncommon','Ungewöhnlich'),rare:t('Rare','Selten'),epic:t('Epic','Episch'),legendary:t('Legendary','Legendär')};
    const bars=m.earnings.map(row=>`<li class="stat-income-${row.id}"><span>${earningsNames[row.id]}</span><strong>${justizEuro(row.amount)}</strong><div class="stat-bar" aria-hidden="true"><i style="width:${m.earned?row.amount/m.earned*100:0}%"></i></div></li>`).join('');
    const rarity=c.rarities.map(row=>`<li class="stat-rarity-${row.id}"><span>${rarityNames[row.id]}</span><strong>${number(row.count)}</strong><div class="stat-bar" aria-hidden="true"><i style="width:${c.opened?row.count/c.opened*100:0}%"></i></div></li>`).join('');
    return `<div class="profile-statistics"><header class="statistics-heading"><div><h2>${t('Statistics','Statistiken')}</h2><p>${t('Recorded lifetime totals · preserved through Prestige','Erfasste Gesamtsummen · bleiben bei Prestige erhalten')}${infoTip(t('Based on saved receipts. Older or administratively reset activity may be incomplete. Starting money, bid deposits, refunds and register collections do not count as earnings. Earnings include money still in registers.','Basiert auf gespeicherten Belegen. Ältere oder administrativ zurückgesetzte Aktivitäten können unvollständig sein. Startgeld, Gebotskautionen, Erstattungen und Kassenleerungen zählen nicht als Einnahmen. Einnahmen enthalten auch Geld in den Kassen.'),t('About these totals','Über diese Summen'))}</p></div><span class="statistics-seal" aria-hidden="true">${icon('stats')}</span></header>
    <dl class="statistics-scoreboard">${statTile(t('Money earned','Geld verdient'),justizEuro(m.earned),'sale')}${statTile(t('Money spent','Geld ausgegeben'),justizEuro(m.spent),'reinvest')}${statTile(t('Net earnings','Netto-Einnahmen'),justizEuro(m.net),'star',t('Recorded earnings minus spending. This is not your available wallet balance.','Erfasste Einnahmen minus Ausgaben. Dies ist nicht dein verfügbares Guthaben.'))}</dl>
    <div class="statistics-breakdowns"><section class="stat-breakdown"><h3>${t('Where your money comes from','Woher dein Geld kommt')}</h3><ul>${bars}</ul></section><section class="stat-breakdown stat-case-haul"><h3>${t('Case rarity haul','Kistenfunde nach Seltenheit')}</h3><ul>${rarity}</ul></section></div>
    <div class="statistics-groups">${statGroup('cases',t('Cases','Kisten'),'find',[
      statTile(t('Cases opened','Kisten geöffnet'),number(c.opened),'find'),statTile(t('Value from cases','Wert aus Kisten'),justizEuro(c.value),'star',t('Sum of saved reference values of revealed case items, rounded to J€. This is not sale revenue or a live market quote.','Summe der gespeicherten Referenzwerte enthüllter Kistenfunde, auf J€ gerundet. Dies sind keine Verkaufseinnahmen oder aktuellen Marktpreise.')),
      statTile(t('Total case cost','Gesamte Kistenkosten'),justizEuro(c.cost),'reinvest'),statTile(t('Cases bought','Kisten gekauft'),number(c.bought),'sale'),statTile(t('Opened case cost','Kosten geöffneter Kisten'),justizEuro(c.openedCost),'reinvest'),statTile(t('Best case find','Bester Kistenfund'),justizEuro(c.bestValue),'star')])}
    ${statGroup('trading',t('Trading','Handel'),'sale',[
      statTile(t('Items sold','Gegenstände verkauft'),number(r.itemsSold),'sale'),statTile(t('Trading profit','Handelsgewinn'),justizEuro(r.profit),'star',t('Sale proceeds less recorded purchase costs and guard wages, excluding free reward items and unknown costs.','Verkaufserlöse minus erfasste Einkaufskosten und Wachgebühren, ohne kostenlose Belohnungen und unbekannte Kosten.')),
      statTile(t('Auctions listed','Auktionen erstellt'),number(r.auctionsListed),'sale'),statTile(t('Auctions won','Auktionen gewonnen'),number(r.auctionWins),'check'),statTile(t('Bids submitted','Gebote abgegeben'),number(r.bids),'reinvest'),statTile(t('Palettes opened','Paletten geöffnet'),number(r.palettesOpened),'find'),statTile(t('Items from palettes','Gegenstände aus Paletten'),number(r.paletteItems),'find')])}
    ${statGroup('stores',t('Business empire','Ladenimperium'),'sale',[
      statTile(t('Stores opened','Läden eröffnet'),number(b.opened),'sale'),statTile(t('Store visitors','Ladenbesucher'),number(b.visitors),'friends',t('Recorded NPC visitors plus unique player visits per store and day.','Erfasste NPC-Besucher plus eindeutige Spielerbesuche pro Laden und Tag.')),statTile(t('Items sold in stores','In Läden verkaufte Artikel'),number(b.sales),'sale'),statTile(t('Store sale revenue','Ladenverkaufserlöse'),justizEuro(b.revenue),'star'),statTile(t('Cash collected','Kassengeld eingesammelt'),justizEuro(b.collected),'reinvest'),statTile(t('Registers emptied','Kassen geleert'),number(b.collections),'reinvest'),statTile(t('Player visits','Spielerbesuche'),number(b.playerVisits),'friends')])}
    ${statGroup('theft',t('Mischief record','Unfugbilanz'),'record',[
      statTile(t('Items stolen','Gegenstände gestohlen'),number(h.stolen),'find'),statTile(t('Theft attempts','Diebstahlversuche'),number(h.attempts),'record'),statTile(t('Times caught','Erwischt worden'),number(h.caught),'record'),statTile(t('Police escapes','Polizei entkommen'),number(h.escaped),'reinvest'),statTile(t('Fines paid in cash','Bußgelder in bar bezahlt'),justizEuro(m.finesPaid),'reinvest'),statTile(t('Fines received','Bußgelder erhalten'),justizEuro(m.finesReceived),'sale')])}
    ${statGroup('games',t('Daily & games','Daily & Spiele'),'daily',[
      statTile(t('Dailies completed','Dailys abgeschlossen'),number(g.dailyCompleted),'daily'),statTile(t('Best Daily score','Beste Daily-Punktzahl'),number(g.bestDailyScore)+' / 5,000','star'),statTile(t('Daily rewards','Daily-Belohnungen'),justizEuro(m.dailyRewards),'daily'),statTile(t('Higher or Lower runs','Höher-oder-Niedriger-Runden'),number(g.higherLowerCompleted),'reinvest'),statTile(t('Best streak','Beste Serie'),number(g.bestStreak),'star'),statTile(t('Higher or Lower rewards','Höher-oder-Niedriger-Belohnungen'),justizEuro(m.higherLowerRewards),'sale'),statTile(t('XP earned','XP verdient'),number(g.xpEarned),'star')])}
    ${statGroup('extras',t('Gifts & expenses','Geschenke & Ausgaben'),'friends',[
      statTile(t('Gifts received','Geschenke erhalten'),justizEuro(m.gifts),'friends'),statTile(t('Tips received','Trinkgeld erhalten'),justizEuro(m.tipsReceived),'sale'),statTile(t('Tips given','Trinkgeld gegeben'),justizEuro(m.tipsGiven),'reinvest'),statTile(t('Guard wages','Wachgebühren'),justizEuro(m.guardCosts),'record'),statTile(t('Prestige resets','Prestige-Resets'),number(k.prestiges),'star'),statTile(t('Verified reviews posted','Verifizierte Bewertungen'),number(k.reviews),'friends')])}</div>
    ${c.unknownCosts||r.unknownCosts||b.unknownCosts?`<p class="statistics-coverage">${t('Some older purchase costs were not recorded. Cost and profit totals include known values only.','Einige ältere Einkaufskosten wurden nicht erfasst. Kosten- und Gewinnsummen enthalten nur bekannte Werte.')}</p>`:''}</div>`;
  }
  function overview(){
    return `${prestigeCard()}${journey()}<div class="profile-play-grid">${dailyCard()}<a class="profile-play-card profile-collection-card" href="/inventory" data-page><span class="profile-card-icon">${icon('find')}</span><div><h2>${number(account.itemCount)} ${t(account.itemCount===1?'item':'items',account.itemCount===1?'Gegenstand':'Gegenstände')}</h2></div><strong>${t('Inventory','Inventar')} →</strong></a></div><section class="profile-wallet" aria-label="${t('Your trading stats','Deine Handelsbilanz')}"><div><span>${t('Trading profit','Handelsgewinn')}</span><strong>${justizEuro(account.realizedTradingProfit||0)}</strong></div><a href="/leaderboard?view=collection" data-page><span>${t('Collection rank','Sammlungsrang')}</span><strong>${t('Leaderboard','Rangliste')} →</strong></a></section><details class="profile-breakdown"><summary>${t('Trading breakdown & rewards','Handelsdetails & Belohnungen')}</summary>${economyOverviewMarkup()}${rewardBanner()}</details>`;
  }
  function render(){
    if(!account){accountContent.innerHTML=pageHeading(t('Profile','Profil'))+loginNotice('profile');return;}
    const tab=selectedTab();
    const content=tab==='statistics'?statistics():tab==='record'?criminalRecordMarkup():tab==='friends'?`<section class="profile-friends"><div class="friends-heading"><div><h2>${t('Friends','Freunde')}</h2></div><button type="button" class="secondary-button" data-account="refresh">${t('Refresh','Aktualisieren')}</button></div>${friendsMarkup()}</section>`:overview();
    accountContent.innerHTML=`<div class="profile-hub">${hero()}${tabs(tab)}<div id="profile-panel" role="tabpanel" aria-labelledby="profile-tab-${tab}">${content}</div><footer class="profile-account-controls"><button type="button" class="secondary-button" data-account="logout">${t('Log out','Abmelden')}</button></footer></div>`;
  }
  function select(tab){
    if(currentAccountPage!=='/profile'||!account||!['overview','statistics','friends','record'].includes(tab))return;
    const query=new URLSearchParams(location.search);if(tab==='overview')query.delete('tab');else query.set('tab',tab);
    history.replaceState({},'','/profile'+(query.size?'?'+query:''));render();accountContent.querySelector(`[data-profile-tab="${tab}"]`)?.focus({preventScroll:true});
  }
  document.addEventListener('click',event=>{const button=event.target.closest('[data-profile-tab]');if(button)select(button.dataset.profileTab);});
  document.addEventListener('keydown',event=>{
    const button=event.target.closest('[data-profile-tab]');if(!button||currentAccountPage!=='/profile')return;
    const ids=['overview','statistics','friends','record'],index=ids.indexOf(button.dataset.profileTab);
    const next=event.key==='ArrowRight'?(index+1)%ids.length:event.key==='ArrowLeft'?(index+ids.length-1)%ids.length:event.key==='Home'?0:event.key==='End'?ids.length-1:null;
    if(next!==null){event.preventDefault();select(ids[next]);}
  });
  return {render};
})();
